package io.github.g20ir.db

import io.github.g20ir.model.CodeSet
import org.json.JSONObject

/** The bundled code database (assets/irdb.json, generated by tools/build_irdb.py). */
class CodeDatabase(json: String) {
    private val root = JSONObject(json)
    private val db = root.getJSONObject("db")
    val source: String = root.getJSONObject("meta").optString("source")

    val categories: List<String> = db.keys().asSequence().toList()

    /** Brands of a category, the ones with the most known models first. */
    fun brands(category: String): List<Brand> {
        val c = db.optJSONObject(category) ?: return emptyList()
        return c.keys().asSequence().map { name ->
            val arr = c.getJSONArray(name)
            var models = 0
            for (i in 0 until arr.length()) models += arr.getJSONObject(i).getJSONArray("m").length()
            Brand(name, arr.length(), models)
        }.sortedWith(compareByDescending<Brand> { it.models }.thenBy { it.name.lowercase() }).toList()
    }

    fun codeSets(category: String, brand: String): List<CodeSet> {
        val arr = db.optJSONObject(category)?.optJSONArray(brand) ?: return emptyList()
        return List(arr.length()) { CodeSet.fromJson(brand, category, arr.getJSONObject(it)) }
    }

    data class Brand(val name: String, val codeSets: Int, val models: Int)
}
